   guard();
   const latest=value.sourceCardId?existing.cards.find(item=>item.id===value.sourceCardId)?.attachment:value.attachment;
   if(!latest||['dataUrl','type','size','name'].some(key=>latest[key]!==snapshot[key]))throw Error('原音频在保存期间变化，片段未保存；字幕、备注和时间标记已保留。');
