  catch(issue){finalRecord=normalizePodcastTranscription({...record,phase:'failed',error:issue.code==='AI_CONFIRMATION_REQUIRED'?'本次转录已取消，未自动重试':issue.message||'本次转录未完成，未自动重试',updatedAt:new Date().toISOString()});}
